pub const SLOT_NAMES: [&str; 10] = [
    "Head",
    "Shoulder",
    "Chest",
    "Waist",
    "Legs",
    "Feet",
    "Wrist",
    "Hands",
    "Main Hand",
    "Off Hand",
];
fn slot_name(catalog: &ArmoryCatalog, class: u8, slot: usize) -> &'static str {
    if slot == 14 {
        "Back"
    } else if slot == 8
        && catalog
            .class(class)
            .items
            .iter()
            .any(|p| p.slot == slot && p.slot_id == 17)
    {
        "Ranged"
    } else {
        SLOT_NAMES[slot]
    }
}

#[derive(Deserialize)]
struct GearNameRules {
    classes: Vec<GearNameClass>,
    nouns: BTreeMap<String, Vec<String>>,
}
#[derive(Deserialize)]
struct GearNameClass {
    id: u8,
    key: String,
    material: String,
    sets: Vec<GearNameSet>,
}
#[derive(Deserialize)]
struct GearNameSet {
    fallback: String,
    suffix: bool,
}

fn translated<'a>(catalog: &'a MenuCatalog, key: &str, fallback: &'a str) -> &'a str {
    catalog
        .labels
        .get(key)
        .map(String::as_str)
        .unwrap_or(fallback)
}

/// Current1459a4ba0 names armor through native set/noun grammar and weapons through
/// their class/PvP key. The English fallback stays independent of locale overrides.
pub(crate) fn piece_lore(catalog: &MenuCatalog, piece: &GearPiece, class: u8) -> String {
    let index = (usize::from(class) * 3 + piece.slot) % 8;
    let key = if piece.rarity < 3 {
        format!("lore.plain.{index}")
    } else {
        format!("lore.{}.{index}", class_name(class).to_lowercase())
    };
    translated(catalog, &key, &piece.flavor).into()
}

fn name_rules() -> &'static GearNameRules {
    static RULES: OnceLock<GearNameRules> = OnceLock::new();
    RULES.get_or_init(|| {
        serde_json::from_str(include_str!("../assets/armory-name-rules-0.109.0.json"))
            .expect("selected-target gear name grammar")
    })
}

pub(crate) fn set_name_base(class: u8, tier: usize) -> Option<&'static str> {
    let rule = name_rules().classes.iter().find(|rule| rule.id == class)?;
    if tier == usize::from(TIER_HALF) {
        tier05::class(class).map(|set| set.name.as_str())
    } else if tier == 5 {
        Some(if class == 7 { "Warlord's" } else { "Field Marshal's" })
    } else {
        rule.sets.get(tier).map(|set| set.fallback.as_str())
    }
}

pub(crate) fn set_name(catalog: &MenuCatalog, class: u8, tier: usize) -> String {
    let Some(rule) = name_rules().classes.iter().find(|rule| rule.id == class) else {
        return String::new();
    };
    if tier == usize::from(azeroth_survivors_re::sets::TIER_HALF) {
        let fallback = set_name_base(class, tier).unwrap_or("");
        translated(catalog, &format!("set.{}.{tier}", rule.key), fallback).into()
    } else if tier == 5 {
        let fallback = if class == 7 { "Warlord's" } else { "Field Marshal's" };
        translated(catalog, &format!("set.pvp.{fallback}"), fallback).into()
    } else {
        let Some(set) = rule.sets.get(tier) else { return String::new(); };
        translated(catalog, &format!("set.{}.{tier}", rule.key), &set.fallback).into()
    }
}

pub(crate) fn set_four_bonus(labels: &MenuCatalog, class: u8, tier: u8) -> String {
    if tier == azeroth_survivors_re::sets::TIER_HALF {
        return azeroth_survivors_re::sets::tier_half_four_piece(class)
            .map_or_else(String::new, |bonus| labels.label(&bonus.description));
    }
    azeroth_survivors_re::sets::four_piece_effects(tier).iter()
        .map(|&(tag, value)| localized_bonus(labels, u32::from(tag), value))
        .collect::<Vec<_>>().join(", ")
}

pub(crate) fn set_eight_bonus(labels: &MenuCatalog, class: u8, tier: u8, empowered: bool)
    -> Option<String>
{
    let descriptor = azeroth_survivors_re::sets::descriptor(class, tier, empowered)?;
    Some(labels.label(&descriptor.description)
        .replace("{v}", &native_decimal(descriptor.display_values[0]))
        .replace("{v2}", &native_decimal(descriptor.display_values[1])))
}

pub(crate) fn piece_name(catalog: &MenuCatalog, piece: &GearPiece, race: u8) -> String {
    let rules = name_rules();
    let fallback = piece.name(race);
    if let Some(key) = piece.tier05_name_key() {
        return translated(catalog, &key, fallback).into();
    }
    let class = ((piece.id.saturating_sub(100000)) / 1000) as u8;
    let Some(rule) = rules.classes.iter().find(|rule| rule.id == class) else {
        return fallback.into();
    };
    if piece.slot >= 8 {
        let key = if piece.rarity == 5 {
            format!("weapon.pvp.{fallback}")
        } else {
            format!("weapon.{}.{}.{}", rule.key, piece.slot - 8, piece.rarity)
        };
        return translated(catalog, &key, fallback).into();
    }
    let noun = &rules.nouns[&rule.material][piece.slot];
    let (set_key, set_fallback, suffix) = if piece.rarity == 5 {
        let Some(set) = fallback.strip_suffix(&format!(" {noun}")) else {
            return fallback.into();
        };
        (format!("set.pvp.{set}"), set, false)
    } else {
        let Some(set) = rule.sets.get(piece.rarity) else {
            return fallback.into();
        };
        (
            format!("set.{}.{}", rule.key, piece.rarity),
            set.fallback.as_str(),
            set.suffix,
        )
    };
    let key = if suffix {
        "item.name_of"
    } else {
        "item.name_prefix"
    };
    translated(
        catalog,
        key,
        if suffix {
            "{noun} of {set}"
        } else {
            "{set} {noun}"
        },
    )
    .replace(
        "{noun}",
        translated(
            catalog,
            &format!("noun.{}.{}", rule.material, piece.slot),
            noun,
        ),
    )
    .replace("{set}", translated(catalog, &set_key, set_fallback))
}

pub(crate) fn cosmetic_name<'a>(labels: &'a MenuCatalog, entry: &'a cosmetics::Cosmetic) -> &'a str {
    translated(labels, &format!("cosmetic.{}", entry.id), &entry.name)
}

pub(crate) fn starter_name<'a>(labels: &'a MenuCatalog, item: &'a StarterItem) -> &'a str {
    translated(labels, &format!("starter.{}", item.id), &item.name)
}

fn slot_label(catalog: &MenuCatalog, gear: &ArmoryCatalog, class: u8, slot: usize) -> String {
    translated(
        catalog,
        &format!("slot.{}", native_slot(class, slot)),
        slot_name(gear, class, slot),
    )
    .into()
}

fn zone_label(catalog: &MenuCatalog, zone: &DropZone) -> String {
    translated(catalog, &format!("zone.{}.name", zone.key), &zone.name).into()
}
fn boss_label(catalog: &MenuCatalog, zone: &DropZone, index: usize) -> String {
    let fallback = &zone.bosses[index].name;
    let key = catalog
        .zones
        .iter()
        .find(|entry| entry.key == zone.key)
        .and_then(|entry| entry.bosses.get(index))
        .map(|entry| entry.name.as_str());
    key.unwrap_or(fallback).into()
}

const SLOT_ART: [&str; 10] = [
    "Head",
    "Shoulder",
    "Chest",
    "Waist",
    "Legs",
    "Feet",
    "Wrist",
    "Hands",
    "MainHand",
    "SecondaryHand",
];
// Current1400fe650 filters this native paperdoll sequence through1400f8890.
const EQUIPMENT_ORDER: [usize; 12] = [0, 2, 14, 4, 9, 8, 5, 6, 7, 15, 16, 17];

fn equipment_slots(catalog: &ArmoryCatalog, class: u8, gear: &GearSave) -> Vec<usize> {
    EQUIPMENT_ORDER
        .into_iter()
        .filter_map(|native| {
            catalog
                .class(class)
                .items
                .iter()
                .find(|piece| usize::from(piece.slot_id) == native)
                .map(|piece| piece.slot)
                .or_else(|| {
                    cosmetics::all()
                        .iter()
                        .any(|entry| entry.slot == native && gear.granted.contains(&entry.id))
                        .then_some(native)
                })
        })
        .collect()
}

fn slot_art(class: u8, slot: usize) -> &'static str {
    match native_slot(class, slot) {
        14 => "Chest",
        17 => "Ranged",
        _ => SLOT_ART[slot],
    }
}
