fn piece_icon(
    ui: &mut ChildSpawnerCommands,
    art: &MenuArt,
    menu_catalog: &MenuCatalog,
    p: &GearPiece,
    b: [f32; 4],
    gear: &GearSave,
    class: u8,
    race: u8,
) {
    // Current140247090 ->1400e32f0 puts Act/Interaction/ImageNode on one entity.
    // A separate image sibling would intercept this cell's native hover action.
    let mut node = menu::rect(b);
    node.border = UiRect::all(Val::Px(1.));
    node.border_radius = BorderRadius::all(Val::Px(4.));
    let mut cell = ui.spawn((
        Button,
        ArmoryAction::Piece(p.id),
        node,
        Face {
            selected: false,
            primary: false,
            disabled: false,
        },
        BackgroundColor(DARK),
        BorderColor::all(EDGE),
    ));
    if let Some(image) = art.icons.get(&format!("gear.{}", p.display_id(race))) {
        cell.insert(ImageNode {
            color: if gear.owned.contains(&p.id) {
                Color::WHITE
            } else {
                Color::srgb(0.35, 0.35, 0.35)
            },
            ..ImageNode::new(image.clone())
        });
    }
    cell.with_children(|ui| {
        if !gear.owned.contains(&p.id) {
            menu::caption(ui, art, "?", 17., [0., b[3] * 0.27, b[2], 22.], MUTED, true);
        }
        if gear.worn(class, p.slot) == Some(p.id) {
            piece_badge(
                ui,
                art,
                menu_catalog.label("armory.mark_worn"),
                GOLD,
                true,
            );
        }
        if gear.cosmetic(class, p.slot) == Some(p.id) {
            piece_badge(
                ui,
                art,
                menu_catalog.label("armory.mark_look"),
                Color::srgb(0.29, 0.549, 1.),
                false,
            );
        }
    });
}

