/// Native03bc70→1f4550 shared header: a growing title column and intrinsic-width tabs.
pub fn build_header_row(
    ui: &mut ChildSpawnerCommands,
    art: &MenuArt,
    menu_catalog: &MenuCatalog,
    state: &MenuState,
) {
    static CATALOG: OnceLock<ArmoryCatalog> = OnceLock::new();
    let catalog = CATALOG.get_or_init(ArmoryCatalog::embedded);
    let gear = GearSave::read_for(&state.save, state.class_id(), state.race);
    let class = state.class_id();
    let def = catalog.class(class);
    let class_def = &menu_catalog.classes[state.class];
    ui.spawn(Node {
        width: Val::Percent(100.),
        column_gap: Val::Px(14.),
        align_items: AlignItems::Center,
        ..default()
    })
    .with_children(|header| {
        header
            .spawn(Node {
                flex_direction: FlexDirection::Column,
                flex_grow: 1.,
                ..default()
            })
            .with_children(|title| {
                title.spawn((
                    Text::new(menu_catalog.label("picker.armory")),
                    TextFont {
                        font: art.heading_font.clone(),
                        font_size: 46.,
                        ..default()
                    },
                    TextColor(GOLD),
                    TextShadow {
                        offset: Vec2::new(0., 3.),
                        ..menu::native_text_shadow()
                    },
                ));
                let collected = crate::localization::format(
                    menu_catalog,
                    "armory.collected_line",
                    &[
                        ("n", gear.count(catalog, class).to_string()),
                        ("total", def.items.len().to_string()),
                    ],
                );
                title
                    .spawn((
                        Text::new(&class_def.name),
                        TextFont {
                            font: art.font.clone(),
                            font_size: 15.,
                            ..default()
                        },
                        TextColor(Color::srgb(
                            class_def.color[0],
                            class_def.color[1],
                            class_def.color[2],
                        )),
                        menu::native_text_shadow(),
                    ))
                    .with_children(|line| {
                        line.spawn((
                            TextSpan::new(format!("  ·  {collected}")),
                            TextFont {
                                font: art.font.clone(),
                                font_size: 15.,
                                ..default()
                            },
                            TextColor(MUTED),
                        ));
                    });
            });
        let talent_points = crate::talents::available_points(&state.save, class);
        let reward_points = crate::progression::available_points(&state.save);
        for (page, _) in Page::TABS {
            let points = match page {
                Page::Talents => talent_points,
                Page::Rewards => reward_points,
                _ => 0,
            };
            let name = menu_catalog.label(crate::localization::tab_key(page));
            let text = if points > 0 {
                format!("{name} ({points})")
            } else {
                name.into()
            };
            header_button(
                header,
                art,
                &text,
                Action::Page(page),
                state.page == page,
                16.,
            );
        }
        header.spawn(Node {
            width: Val::Px(18.),
            ..default()
        });
        header_button(
            header,
            art,
            menu_catalog.label("options.done"),
            Action::Picker,
            true,
            18.,
        );
    });
}
/// Native03b3f0: auto dimensions,14×6 padding,1px border and5px radius.
fn header_button<A: Component>(
    ui: &mut ChildSpawnerCommands,
    art: &MenuArt,
    text: &str,
    action: A,
    selected: bool,
    size: f32,
) {
    let resting = if selected { GOLD } else { EDGE };
    let mut button = ui.spawn((
        Button,
        action,
        Face {
            selected,
            primary: selected,
            disabled: false,
        },
        NativeHover::new(resting, Color::srgb(1., 0.914, 0.659), 0.),
        Node {
            padding: UiRect::axes(Val::Px(14.), Val::Px(6.)),
            border: UiRect::all(Val::Px(1.)),
            border_radius: BorderRadius::all(Val::Px(5.)),
            align_items: AlignItems::Center,
            justify_content: JustifyContent::Center,
            ..default()
        },
        BorderColor::all(resting),
    ));
    if selected {
        button.insert(menu::native_button_gradient());
    } else {
        button.insert(BackgroundColor(Color::srgba(0., 0., 0., 0.5)));
    }
    button.with_children(|label| {
        label.spawn((
            Text::new(text),
            TextFont {
                font: art.font.clone(),
                font_size: size,
                ..default()
            },
            TextColor(if selected {
                Color::srgb(1., 0.914, 0.659)
            } else {
                GOLD
            }),
            menu::native_text_shadow(),
        ));
    });
}

pub fn build(
    ui: &mut ChildSpawnerCommands,
    art: &MenuArt,
    menu_catalog: &MenuCatalog,
    state: &MenuState,
    preview: &HeroPreviewOutput,
    catalog: &ArmoryCatalog,
    view: &ArmoryState,
) {
    let gear = GearSave::read_for(&state.save, state.class_id(), state.race);
    ui.spawn(shell_node()).with_children(|ui| {
        build_header_row(ui, art, menu_catalog, state);
        let mut body = body_node();
        body.min_height = Val::Px(0.);
        ui.spawn(body).with_children(|ui| {
            left(ui, art, menu_catalog, state, catalog, view, &gear);
            match state.page {
                Page::Character => {
                    character(ui, art, menu_catalog, state, preview, catalog, view, &gear)
                }
                Page::Collection => collection(ui, art, menu_catalog, state, catalog, view, &gear),
                Page::DropTables => drops(ui, art, menu_catalog, state, catalog, view, &gear),
                _ => {}
            }
        });
    });
}
/// Native equipped effects, formatted for the picker with its middle-dot separator.
pub fn equipment_summary(
    save: &Save,
    class: u8,
    catalog: &ArmoryCatalog,
    menu_catalog: &MenuCatalog,
) -> Option<String> {
    let gear = GearSave::read(save);
    let mut sum = BTreeMap::<u32, f32>::new();
    for (tag, value) in gear.effects(catalog, class) {
        *sum.entry(u32::from(tag)).or_default() += value;
    }
    (!sum.is_empty()).then(|| {
        sum.into_iter()
            .map(|(tag, value)| localized_bonus(menu_catalog, tag, value))
            .collect::<Vec<_>>()
            .join(" · ")
    })
}
