    #[test]
    fn all_nineteen_outfit_lanes_match_current_original_vectors() {
        let catalog = ArmoryCatalog::embedded();
        for case in save_gear_vectors()["outfit"].as_array().unwrap() {
            let class = case["class_id"].as_u64().unwrap() as u8;
            let race = case["race"].as_u64().unwrap() as u8;
            let mut gear = GearSave::default();
            gear.races.insert(class, race);
            for (slot, value) in case["equip"].as_array().unwrap().iter().enumerate() {
                let id = value.as_u64().unwrap() as u32;
                if id != 0 {
                    gear.equipped.insert((class, slot), id);
                    gear.owned.insert(id);
                }
            }
            for (slot, value) in case["look"].as_array().unwrap().iter().enumerate() {
                if let Some(id) = value.as_u64().map(|id| id as u32) {
                    gear.looks.insert((class, slot), id);
                    if crate::save::gear::decode(id).is_some() {
                        gear.owned.insert(id);
                    }
                    if matches!(id, 90_001..=90_006 | 90_011..=90_024) {
                        gear.granted.insert(id);
                    }
                }
            }
            assert_eq!(
                serde_json::to_value(gear.outfit(&catalog, class, race)).unwrap(),
                case["expected"],
                "{case}"
            );
            let mut expected = gear.outfit(&catalog, class, race);
            if expected[15] != 0 || expected[16] != 0 {
                expected[17] = 0;
            }
            assert_eq!(gear.menu_outfit(&catalog, class, race), expected);
        }
    }

