    #[test]
    fn starting_clothes_hidden_and_worn_roundtrip_without_collection_ownership() {
        let catalog = ArmoryCatalog::embedded();
        let (race, class, slot) = (1, 8, 2);
        let lane = native_slot(class, slot);
        let starter = catalog.starter_look(race, class, lane).unwrap();
        let mut save = Save::parse("").unwrap();
        let mut gear = GearSave::read_for(&save, class, race);
        assert!(!gear.owned.contains(&starter));
        for appearance in [Some(starter), Some(0), None] {
            assert!(gear.set_look(&catalog, class, slot, appearance));
            gear.apply(&mut save).unwrap();
            gear = GearSave::read_for(&save, class, race);
            assert_eq!(gear.cosmetic(class, slot), appearance);
            assert_eq!(gear.outfit(&catalog, class, race)[lane], appearance.unwrap_or(starter));
            assert!(!gear.owned.contains(&starter));
        }
        assert!(!gear.set_look(&catalog, class, 0, Some(starter)));
    }

