    #[test]
    fn pvp_equipment_and_cosmetic_controls_round_trip_without_granting_stats_or_ownership() {
        let catalog = ArmoryCatalog::embedded();
        let mut save = Save::parse("items|101050,101850\nstat|kills=42\n").unwrap();
        let mut gear = GearSave::read(&save);
        assert!(!gear.secondary_piece(&catalog, 1, 101150, false));
        assert!(!gear.secondary_piece(&catalog, 2, 101050, false));
        assert!(gear.secondary_piece(&catalog, 1, 101050, true));
        assert!(
            gear.effects(&catalog, 1).is_empty(),
            "appearance grants no stats"
        );
        assert!(gear.secondary_piece(&catalog, 1, 101050, false));
        assert!(gear.secondary_piece(&catalog, 1, 101850, false));
        let worn = gear.effects(&catalog, 1);
        assert_eq!(
            worn.iter()
                .filter(|(tag, _)| *tag == 2)
                .map(|(_, v)| *v)
                .sum::<f32>(),
            34.
        );
        gear.apply(&mut save).unwrap();
        let mut loaded = GearSave::read(&Save::parse(&save.plaintext()).unwrap());
        assert_eq!(loaded.effects(&catalog, 1), worn);
        assert_eq!(loaded.cosmetic(1, 0), Some(101050));
        assert!(loaded.secondary_slot(1, 0, false));
        assert_eq!(loaded.cosmetic(1, 0), Some(101050));
        assert!(!loaded.effects(&catalog, 1).iter().any(|(tag, _)| *tag == 2));
        assert!(loaded.secondary_slot(1, 8, false));
        assert!(loaded.effects(&catalog, 1).is_empty());
        assert_eq!(loaded.owned, BTreeSet::from([101050, 101850]));
        assert!(save.plaintext().contains("stat|kills=42\n"));
    }

    #[test]
    fn pvp_buttons_deliver_selection_equip_look_and_modal_gating_through_live_input() {
        struct CaptureGuard(Option<std::ffi::OsString>);
        impl Drop for CaptureGuard {
            fn drop(&mut self) {
                if let Some(value) = &self.0 {
                    std::env::set_var("WOW_CAPTURE", value);
                } else {
                    std::env::remove_var("WOW_CAPTURE");
                }
            }
        }
        // A capture fixture has no config home; it cannot read an installed profile.
        let _capture = CaptureGuard(std::env::var_os("WOW_CAPTURE"));
        std::env::set_var("WOW_CAPTURE", "pvp-input-fixture");
        let mut state = MenuState::from_save_path(None);
        state.page = Page::Collection;
        state.save = Save::parse("items|101050\n").unwrap();
        let mut app = App::new();
        app.insert_resource(state)
            .init_resource::<ArmoryState>()
            .init_resource::<ArmoryCatalog>()
            .insert_resource(MenuCatalog::embedded())
            .init_resource::<MenuArt>()
            .init_resource::<crate::options::OptionsState>()
            .init_resource::<ButtonInput<MouseButton>>()
            .add_systems(Update, input);
        fn click(app: &mut App, action: ArmoryAction) {
            app.world_mut()
                .resource_mut::<ButtonInput<MouseButton>>()
                .clear();
            app.world_mut()
                .resource_mut::<ButtonInput<MouseButton>>()
                .press(MouseButton::Left);
            let cell = app
                .world_mut()
                .spawn((
                    Button,
                    Interaction::Pressed,
                    action,
                    Face {
                        selected: false,
                        primary: false,
                        disabled: false,
                    },
                ))
                .id();
            app.update();
            app.world_mut().despawn(cell);
        }
        click(&mut app, ArmoryAction::Piece(101050));
        assert_eq!(app.world().resource::<ArmoryState>().selected, Some(101050));
        click(&mut app, ArmoryAction::Equip(101050));
        let state = app.world().resource::<MenuState>();
        assert_eq!(
            GearSave::read_for(&state.save, state.class_id(), state.race).worn(1, 0),
            Some(101050)
        );
        let revision = state.save_revision;
        app.world_mut().resource_mut::<MenuState>().dialog = Some(crate::menu_state::Dialog::Menu);
        click(&mut app, ArmoryAction::Equip(101050));
        assert_eq!(app.world().resource::<MenuState>().save_revision, revision);
        app.world_mut().resource_mut::<MenuState>().dialog = None;
        click(&mut app, ArmoryAction::Look(0, Some(101050)));
        click(&mut app, ArmoryAction::Equip(101050));
        let state = app.world().resource::<MenuState>();
        let gear = GearSave::read_for(&state.save, state.class_id(), state.race);
        assert_eq!(gear.cosmetic(1, 0), Some(101050));
        assert_eq!(gear.worn(1, 0), None);
        assert!(gear
            .effects(app.world().resource::<ArmoryCatalog>(), 1)
            .is_empty());
        assert!(state.error.is_none());
    }

    #[test]
    fn drop_controls_match_live_candidate_ids() {
        let catalog = ArmoryCatalog::embedded();
        assert_eq!(catalog.zones.len(), 13);
        assert_eq!(catalog.zones[scholomance::INDEX].tier, usize::from(TIER_HALF));
        for hero in &catalog.classes {
            for (zone, definition) in catalog.zones.iter().enumerate() {
                for boss in 0..5 {
                    let displayed = catalog
                        .pieces_for_boss(hero.id, zone, boss)
                        .into_iter()
                        .map(|p| p.id)
                        .collect::<Vec<_>>();
                    let rolled = if zone == scholomance::INDEX {
                        if let Some(slots) = tier05::ARMOR_DROP_SLOTS.get(boss) {
                            slots.iter().map(|&slot| tier05::item_id(hero.id, slot)).collect()
                        } else {
                            tier05::weapon_ids(hero.id).collect()
                        }
                    } else {
                        let legacy = azeroth_survivors_re::mob_loot::BOSS_ZONES.iter()
                            .position(|row| row.key == definition.key).unwrap();
                        azeroth_survivors_re::mob_loot::boss_candidates(hero.id, legacy, boss)
                            .into_iter()
                            .map(|p| p.item_id)
                            .collect::<Vec<_>>()
                    };
                    assert_eq!(
                        displayed, rolled,
                        "class {} {} boss {boss}",
                        hero.id, definition.key
                    );
                }
            }
        }
        for zone in [8, 9] {
            assert_eq!(catalog.zones[zone].tier, 5);
            assert_eq!(catalog.zones[zone].drop_percent, 25);
        }
        assert_eq!(
            catalog.zones[11].tier, 4,
            "Legendary ID digit must stay four"
        );
    }

    #[test]
    fn saved_pvp_ids_feed_live_health_damage_and_critical_consumers() {
        use crate::gameplay::mechanics::{Mechanics, RunPlayerStats, RunRules};
        let catalog = ArmoryCatalog::embedded();
        for (head, weapon) in [(101050, 101850), (101060, 101860)] {
            let save = Save::parse(&format!(
                "items|{head},{weapon}\nequip|1|0:{head},15:{weapon}\n"
            ))
            .unwrap();
            let effects = GearSave::read(&save).effects(&catalog, 1);
            let mut game = Mechanics::new(
                "elwynn",
                "warrior",
                RunRules { heroic_rank: 0,
                    difficulty: 1.,
                    density_percent: 100,
                    hp_percent: 100,
                    damage_percent: 100,
                    speed_percent: 100,
                    endless: false,
                },
                RunPlayerStats {
                    maximum_health: 100.,
                    health_per_level: 9.,
                    health_multiplier: 1.,
                    regeneration: 0.,
                    pickup_radius: 9.,
                    luck_bonus: 0.,
                    heal_on_kill: 0.,
                    armor_fraction: 0.,
                    damage_reduction: 0.,
                    damage_multiplier: 1.,
                    cooldown_multiplier: 1.,
                    critical_chance: 0.,
                    critical_multiplier: 2.,
                    experience_multiplier: 1.,
                    gold_multiplier: 1.,
                    native_race: 1,
                    packed_player_field: u32::from_le_bytes([1, 1, 0, 0]),
                },
                [1, 2, 3, 4],
            )
            .unwrap();
            game.configure_effects(&[], &effects);
            // Independent selected-native PvP values, including roundf health and
            // the head/weapon's merged flavor contributions. Exercise live refresh.
            assert_eq!(game.max_health(), 134.);
            assert_eq!(game.stats.damage_multiplier, 1. + 0.335999995470047_f32);
            assert_eq!(
                game.stats.critical_chance,
                0.04829999804496765_f32 + 0.02029999904334545_f32
            );
            assert!(
                equipment_summary(&save, 1, &catalog, &MenuCatalog::embedded())
                    .unwrap()
                    .contains("max health")
            );
            game.configure_effects(&[], &[]);
            assert_eq!(game.max_health(), 100.);
            assert_eq!(game.stats.damage_multiplier, 1.);
            assert_eq!(game.stats.critical_chance, 0.);

            let mut pickup = GearSave::default();
            pickup.owned.extend([101350, 101750]);
            assert!(pickup.secondary_piece(&catalog, 1, 101350, false));
            assert!(pickup.secondary_piece(&catalog, 1, 101750, false));
            let effects = pickup.effects(&catalog, 1);
            assert_eq!(effects.iter().filter(|(tag, _)| *tag == 8).count(), 1);
            game.configure_effects(&[], &effects);
            // Native waist/glove bonuses add before multiplying pickup reach.
            assert_eq!(
                game.stats.pickup_radius,
                9. * (1. + (0.335999995470047_f32 + 1.6800000667572021_f32))
            );
        }
    }

    #[test]
    fn secondary_mutations_match_current_native_instruction_cases() {
        let catalog = ArmoryCatalog::embedded();
        for row in native_vectors()["mutations"].as_array().unwrap() {
            let id = row["item"].as_u64().unwrap() as u32;
            let class = ((id - 100000) / 1000) as u8;
            let piece = catalog
                .class(class)
                .items
                .iter()
                .find(|piece| piece.id == id)
                .unwrap();
            let slot = row["slot"].as_u64().unwrap() as usize;
            assert_eq!(piece.slot_id as usize, slot);
            let key = (class, slot);
            let worn = row["worn"].as_u64().unwrap() as u32;
            let mut gear = GearSave::default();
            gear.owned.insert(id);
            gear.equipped.insert((11, 0), 111000);
            gear.looks.insert((11, 0), 0);
            if worn != 0 {
                gear.equipped.insert(key, worn);
            }
            if let Some(look) = row["look"].as_u64() {
                gear.looks.insert(key, look as u32);
            }
            let shift = row["shift"].as_bool().unwrap();
            let changed = if row["action"] == "piece" {
                gear.secondary_piece(&catalog, class, id, shift)
            } else {
                gear.secondary_slot(class, piece.slot, shift)
            };
            assert_eq!(changed, row["changed"].as_bool().unwrap(), "{row}");
            assert_eq!(
                gear.equipped.get(&key).copied().unwrap_or(0),
                row["after_worn"].as_u64().unwrap() as u32,
                "{row}"
            );
            assert_eq!(
                gear.looks.get(&key).copied().map(u64::from),
                row["after_look"].as_u64(),
                "{row}"
            );
            assert_eq!(gear.equipped[&(11, 0)], 111000);
            assert_eq!(gear.looks[&(11, 0)], 0);
            assert_eq!(gear.owned, BTreeSet::from([id]));
        }
    }

    #[test]
    fn secondary_piece_requires_owned_valid_definition_and_preserves_other_save_records() {
        let catalog = ArmoryCatalog::embedded();
        let mut save =
            Save::parse("items|101000\nlook|1|0:0\nstat|kills=42\nunknown|retained\n").unwrap();
        let mut gear = GearSave::read(&save);
        let before = gear.clone();
        assert!(!gear.secondary_piece(&catalog, 1, 101010, false));
        assert!(!gear.secondary_piece(&catalog, 1, u32::MAX, true));
        assert_eq!(gear, before);
        assert!(gear.secondary_piece(&catalog, 1, 101000, true));
        assert_eq!(gear.cosmetic(1, 0), Some(101000));
        assert_eq!(gear.worn(1, 0), None);
        gear.apply(&mut save).unwrap();
        assert!(save.plaintext().contains("stat|kills=42\n"));
        assert!(save.plaintext().contains("unknown|retained\n"));
        assert_eq!(GearSave::read(&save).owned, BTreeSet::from([101000]));
    }

    #[test]
    fn secondary_mouse_filter_matches_native_message_cases() {
        use bevy::input::ButtonState;
        for row in native_vectors()["mouse_messages"].as_array().unwrap() {
            let button = match row["button"].as_u64().unwrap() {
                0 => MouseButton::Left,
                1 => MouseButton::Right,
                2 => MouseButton::Middle,
                3 => MouseButton::Back,
                4 => MouseButton::Forward,
                _ => MouseButton::Other(0),
            };
            let state = if row["state"] == 0 {
                ButtonState::Pressed
            } else {
                ButtonState::Released
            };
            let message = MouseButtonInput {
                button,
                state,
                window: Entity::PLACEHOLDER,
            };
            assert_eq!(
                secondary_press(&message),
                row["accepted"].as_bool().unwrap()
            );
        }
    }
